/* ===== Settings, What's new, mail notices, letters, unlocks, bandana ===== */
function setMute(m){ soundMute = m; soundOn = !soundMute && soundLevel > 0; soundVol = soundOn ? 2 : 0; try { localStorage.setItem("dengame-mute", m ? "1" : "0"); } catch(e){} audioUnlock(); renderHud(); }
function setVolume(v){ soundLevel = Math.max(0, Math.min(100, Math.round(v))); soundOn = !soundMute && soundLevel > 0; soundVol = soundOn ? 2 : 0; try { localStorage.setItem("dengame-vol", String(soundLevel)); } catch(e){} if (AU.master) AU.master.gain.value = soundLevel / 100 * 0.9; }
function openSettings(){ if (document.querySelector(".setov")) return; const ov = document.createElement("div"); ov.className = "sos-ov setov";
  const draw = () => { ov.innerHTML = `<div class="sos-card setcard"><div class="jar-top"><h3>⚙️ Settings</h3><button class="x" data-close aria-label="Close">×</button></div>
    <div class="setrow"><span><b>Sound</b><span class="small">Turn all game sounds on or off</span></span><button class="${soundMute ? "" : "go"}" data-set="mute">${soundMute ? "🔇 Off" : "🔊 On"}</button></div>
    <div class="setrow"><span><b>Volume</b><span class="small" id="volnum">${soundLevel}%</span></span><input type="range" min="0" max="100" step="5" value="${soundLevel}" data-set="vol" aria-label="Volume" style="flex:1;max-width:220px"></div>
    <div class="setrow"><span><b>Weather &amp; lighting</b><span class="small">Full looks best. Light is easier on older computers. Off goes back to the simple look.</span></span><span class="btns">${[["full","Full"],["light","Light"],["off","Off"]].map(([v,l]) => `<button class="${FX.q === v ? "go" : ""}" data-set="fxq" data-v="${v}">${l}</button>`).join("")}</span></div>
    <div class="setrow"><span><b>Gentle weather</b><span class="small">Softer, slower rain and quieter thunder</span></span><button class="${FX.gentle ? "go" : ""}" data-set="fxgentle">${FX.gentle ? "🌦️ On" : "🌦️ Off"}</button></div>
    <div class="setrow"><span><b>Weather sounds</b><span class="small">Rain and wind in the background (thunder always plays with sound on)</span></span><button class="${FX.snd ? "go" : ""}" data-set="fxsnd">${FX.snd ? "🌧️ On" : "🌧️ Off"}</button></div>
    <div class="setrow"><span><b>Camera zoom</b><span class="small" id="zoomlab">${Math.round(camZoom*100)}% · or use the scroll wheel over the Meadow</span></span><input type="range" min="100" max="200" step="5" value="${Math.round(camZoom*100)}" data-set="zoom" aria-label="Camera zoom" style="flex:1;max-width:220px"></div>
    <div class="setrow"><span><b>Interface size</b><span class="small">The game fits itself to your screen. This makes menus and icons bigger or smaller on top of that. Or press − and = in the game.</span></span><span class="btns">${UI_SIZES.map(([v,l]) => `<button class="${+v === uiPref ? "go" : ""}" data-set="uisize" data-v="${v}">${l}</button>`).join("")}</span></div>
    <div class="setrow"><span><b>Self Care (WIP)</b><span class="small">Work in progress. Shows the Self Care tab with Sniffle</span></span><button class="${state && state.selfCareOn ? "go" : ""}" data-set="selfcare">${state && state.selfCareOn ? "🌿 On" : "🌿 Off"}</button></div>
    <div class="setrow"><span><b>Auto-salvage</b><span class="small">More levels in Inventory → cog. Recently salvaged weapons can be undone there too.</span></span><button class="${state && state.hunt && invSalvLevel() ? "go" : ""}" data-set="salvage">${state && state.hunt && invSalvLevel() ? "♻️ On" : "♻️ Off"}</button></div>
    <div class="setrow"><span><b>Overflow bag</b><span class="small">Open it as soon as your bags fill up (otherwise it waits behind a badge on the Inventory button)</span></span><button class="${state && state.inv && state.inv.overPop ? "go" : ""}" data-set="overpop">${state && state.inv && state.inv.overPop ? "🎒 Pop open" : "🎒 Wait"}</button></div>
    <div class="setrow"><span><b>What's new</b><span class="small">Short notes on every update</span></span><button data-set="log">📜 Open${devlogUnseen() ? ` <span class="mdot" style="position:static;display:inline-grid">${devlogUnseen()}</span>` : ""}</button></div>
    <div class="setrow"><span><b>Stats &amp; timeline</b><span class="small">Your play time, level ups and unlocks</span></span><button data-set="stats">📈 Open</button></div>
    <div class="setrow"><span><b>Reload game</b><span class="small">Your progress is saved first</span></span><button data-set="reload">🔄 Reload</button></div><details class="setcred"><summary>Credits</summary>${creditsSection()}</details><details class="setcred"><summary>Developer</summary>${devSection()}</details></div>`; };
  draw(); document.body.appendChild(ov);
  ov.addEventListener("input", e => { const cz = e.target.closest('[data-set="zoom"]'); if (cz){ setZoom(+cz.value / 100); const zl = ov.querySelector("#zoomlab"); if (zl) zl.textContent = cz.value + "% · or use the scroll wheel over the Meadow"; return; } const zr = e.target.closest('[data-set="fkz"]'); if (zr){ fkScale = (+zr.value) / 100; try { localStorage.setItem("dengame-uiscale", String(fkScale)); } catch(e2){} fkApplyScale(); const zl = ov.querySelector("#fkzlab"); if (zl) zl.textContent = zr.value + "% · or press − and = in the game"; return; } const r = e.target.closest('[data-set="vol"]'); if (r){ setVolume(+r.value); const n = ov.querySelector("#volnum"); if (n) n.textContent = soundLevel + "%"; } });
  ov.addEventListener("change", e => { if (e.target.closest('[data-set="vol"]')) sfx("click"); });
  ov.addEventListener("click", e => { if (e.target === ov || e.target.closest("[data-close]")){ ov.remove(); return; } const b = e.target.closest("[data-set]"); if (!b) return;
    if (b.dataset.set === "fxq"){ fxSet("q", b.dataset.v); draw(); return; }
    if (b.dataset.set === "fxgentle"){ fxSet("gentle", !FX.gentle); draw(); return; }
    if (b.dataset.set === "fxsnd"){ fxSet("snd", !FX.snd); draw(); return; }
    if (b.dataset.set === "uisize"){ uiSetPref(+b.dataset.v); draw(); return; }
    if (b.dataset.set === "mute"){ setMute(!soundMute); draw(); }
    if (b.dataset.set === "fklook"){ fkSet(!fkOn); draw(); }
    if (b.dataset.set === "selfcare"){ state.selfCareOn = !state.selfCareOn; save(state.selfCareOn ? "Self Care on" : "Self Care off", true); draw(); render(); }
    if (b.dataset.set === "overpop"){ const I = invState(); I.overPop = !I.overPop; save("Saved", true); draw(); render(); }
    if (b.dataset.set === "salvage"){ invSetSalvLevel(invSalvLevel() ? 0 : 2); save(invSalvLevel() ? "Auto-salvage on" : "Auto-salvage off", true); draw(); render(); }
    if (b.dataset.set === "log"){ ov.remove(); openDevlog(); }
    if (b.dataset.set === "stats"){ ov.remove(); openStats(); }
    if (b.dataset.set === "reload"){ save("Saved before reload"); b.disabled = true; b.textContent = "Saving…"; setTimeout(() => location.reload(), 1200); } }); }

/* What's new — APPEND ONLY. Add a NEW version block at the end for each update (bump the version, one short sentence per line). Never edit or remove old blocks. */
const DEVLOG = [
  {v:"0.1", d:"2026-10-01", notes:["The game got its own home, split off from the Den.","Every player now has their own save.","Experience now comes from hunting."]},
  {v:"0.2", d:"2026-10-01", notes:["Seasonal events are resting while we polish the core game.","The town is closed for now.","Trials, the Trial Pass and daily gifts arrived in the Events tab."]},
  {v:"0.3", d:"2026-10-01", notes:["Added Settings with sound, volume and reload.","Added this What's new list.","Mail now arrives with a gentle popup.","Letters from the Den team now guide you as you grow.","Each tab's menu now sits above the hunting window.","Your canine always wears a bandana."]},
  {v:"0.4", d:"2026-10-01", notes:["Bandanas start in Den Red for now; more colors are coming later."]},
  {v:"0.5", d:"2026-10-01", notes:["New players start with just the Hunt and Armory, and letters unlock the rest as you grow.","Added letters for Upgrades, Bait and Sniffle.","Bones and Trial Points now show as currencies in the Bag."]},
  {v:"0.6", d:"2026-10-01", notes:["Tab menus now sit just below the Head home button.","What's new is now grouped by version."]},
  {v:"0.7", d:"2026-10-01", notes:["The Sanctuary is now a happy home where pups roam free, and their joy fills the air with spirit."]},
  {v:"0.8", d:"2026-10-01", notes:["Hatching is now Rescuing: every new pup is a dog you've given a loving home.","The Bestiary moved into the Library.","The Library now has one menu for Tomes, Bestiary and its rooms.","New Tome of Gathering: essences only drop while it's equipped, and your first one comes in a letter.","The Alembic opens at level 5, the Apothecary once you can brew, and Research, Scrolls and Compendiums at level 10.","The Mine now waits until you can inscribe gems with essences."]},
  {v:"0.9", d:"2026-10-01", notes:["Each area now tracks how comfortable and how overpowered you are there.","An area's Trial opens once you can handle it, with a letter to let you know.","Being overpowered in an area opens its Bestiary pages and a new Meta mode.","Meta mode trials have no timer: keep your power bar up with damage as the waves climb forever.","Fixed the Library not showing its pages under the menu."]},
  {v:"0.10", d:"2026-10-01", notes:["Trading meat for coins now lives right above the Roll button in the Armory.","If you're having a slow start, the Den Team may send up to five care packages with coins and blessings.","Removed leftover Halloween-only tomes, scrolls and gems.","Den decorations are tucked away until they're ready.","Sniffle moved to a new Self Care tab.","Little gift letters now arrive at a few happy milestones."]},
  {v:"0.11", d:"2026-10-01", notes:["Turned off the leftover Halloween sky: no more harvest moon over the sun, bats or pumpkins."]},
  {v:"0.12", d:"2026-10-01", notes:["Fixed saving your auto-roll coin reserve, which could reload the page.","Fixed naming your pups.","The auto-roll coin reserve now starts at 0, since there is no shop yet."]},
  {v:"0.13", d:"2026-10-01", notes:["A device backup can no longer replace a save that has more progress."]},
  {v:"0.14", d:"2026-10-01", notes:["Added Stats & timeline in Settings: play time, level ups, unlocks and a report you can share with the team."]},
  {v:"0.15", d:"2026-10-01", notes:["Added the team to the credits: GrumpyDingo (design) and Firefly (programming)."]},
  {v:"0.16", d:"2026-10-02", notes:["Weapons are now hand-drawn by Firefly: thirteen types, from sticks, tennis balls, flying discs and tug ropes to slingshots, bone clubs, claws, staves, bows and shovels.","Every weapon is built from parts, with its own material, infusion and rarity glow. Embers, frost, lightning, vines, moon runes and smoke are drawn right onto it.","Forging keeps your weapon's look and raises its rarity.","Weapons you already own got a matching new look. Their stats did not change."]},
  {v:"0.17", d:"2026-10-02", notes:["Weapons now drop from creatures out in the wild instead of being rolled for. The Roll button is retired for now.","Each area has its own look: oak and backyard toys in the Meadow, pine and mossjade in the Whispering Forest, moonsilver and ghostwood up in the Moonlit Peaks.","Creatures lean toward dropping the weapon that beats their kind. Flyers drop bows and slingshots, tough hides drop things that bonk.","Two new weapon styles: Tug Ropes yank creatures into reach, and Staves zap up to three creatures with chain sparks.","Auto-salvage turns Common and Uncommon drops that are weaker than your gear into meat. You can turn it off in Settings or the Armory.","Your dingo brings home weapons from away-hunting too.","Epic-or-better pity now counts drops and kicks in within 60."]},
  {v:"0.18", d:"2026-10-02", notes:["New loot feed: weapons and goodies you pick up now slide into a small list in the corner instead of popping up over the screen. Repeats stack up as ×2, ×3 and so on.","Level ups are now a little ribbon over the hunt instead of a big card you have to close.","Beating a mega boss, a god or a trial again shows a banner and the loot feed. First victories, first clears and new bests still get the big celebration.","Trials give your dingo the Zoomies: creatures reach you faster and come more often. In Meta trials, your power drains much slower while nothing is in reach."]},
  {v:"0.19", d:"2026-10-02", notes:["Huge numbers now use short names: K, M, B, T, then Qa, Qi, Sx, Sp, Oc, No, Dc and beyond, so they always stay readable.","Each kill now drops one meat chunk (bigger for bosses) instead of a shower of little meats. It looks cleaner and runs much smoother.","The loot feed now sits on top of the trial and boss bars.","Trial Zoomies got a boost: creatures reach you even faster and come more often, and Meta power barely drains while you're running to the next fight."]},
  {v:"0.20", d:"2026-10-02", notes:["Meta trials: the power bar now fills from kills instead of damage, and it holds steady for 3 seconds after each kill before it starts draining again.","The Firefly Swarm and Meat Meteors events are taking a break for now."]},
  {v:"0.21", d:"2026-10-02", notes:["Rarity now means affixes: Common has none, Uncommon has one, Rare two, Epic three, and Legendary three plus a special power.","A weapon's look matches its affixes. Blazing ones glow with embers, Frostbitten ones grow frost, Crackling ones spark, Clover ones bloom.","Weapon names now come from what they rolled, like Blazing Oak Stick of the Hawk.","Junk weapons no longer drop. The lowest drop is Common. Junk you already own is untouched.","The merge Forge is retired for now. Your forged weapons stay exactly as they are. When your bag is full, your weakest Common or Uncommon turns into meat to make room (locked ones are always safe).","Trial Wardens drop their weapons the new way too.","Auto-equip now starts off for new players, so you choose what your canine carries.","Deleting mail no longer makes old letters arrive again.","Self Care is a work in progress for now: it's off by default and can be switched on in Settings.","No more falling leaves in fall, so the Windy weather stands out. Windy also shows up more often.","Trial and boss banners use the regular game font instead of the Halloween one.","The Stats report button now says Copy report for the Dev Team."]},
  {v:"0.22", d:"2026-10-02", notes:["The Meadow puts on its fall colors in September, October and November: warm skies and a forest of orange, rust and gold.","The Self Care tab stays hidden unless you switch it on in Settings, dev mode included."]},
  {v:"0.23", d:"2026-10-02", notes:["Every season now has its own Meadow look: blossoms in spring, deep greens and bright skies in summer, snowy pines in winter, and fall colors in autumn.","The trees now sit in front of the far mountains.","Settings and other pop-up cards scroll instead of running off the screen.","The Space Invader has left the Meadow. A Wild Bison took its place."]},
  {v:"0.24", d:"2026-10-02", notes:["Rain is gentler: separate soft drops falling at an easy pace instead of a whole sheet of moving stripes, which could feel queasy.","The far mountains sit a little lower, so their base hides behind the tree line in every area."]},
  {v:"0.25", d:"2026-10-02", notes:["The tree line now reaches all the way to the right edge of the scene.","The last Space Invader has left the Meadow at night. A Night Skunk wanders through instead."]},
  {v:"0.26", d:"2026-10-02", notes:["Loot now lands on the ground! Meat, coins and weapons pop out of creatures, bob in place and get picked up as your dingo runs over them. Anything left is pulled in after a few seconds, so nothing is ever lost.","Rare and better weapons land in a little chest with a light beam in their rarity colour: wooden for Rare, iron for Epic, gold for Legendary. Each rarity has its own pickup sound.","Beating a mega boss or a god again leaves a whole pile of loot to scoop up.","Weapons now have a proper item card: a big name plate, its base and style, damage, each affix and power, and where and when you found it. Epic and better cards shimmer.","Weapons moved into the vault are still safe there; the Send to vault button is resting while we design the new Inventory."]},
  {v:"0.27", d:"2026-10-02", notes:["Loot gets pulled into your dingo much faster: it lands, shows off its beam for a moment, then zips straight to you.","The Upgrades tab is resting for now while we reshape the game. Upgrades you already bought still work.","The sound button left the top bar. Sound and volume live in Settings."]},
  {v:"0.28", d:"2026-10-02", notes:["The shimmer on Epic and better item cards now fades in and out smoothly instead of blinking at the end."]},
  {v:"0.29", d:"2026-10-02", notes:["A first look at the new Field Kit style! The hunt fills the whole screen, with your level top-left, the area, time and meat top-right, and a menu dock on the left. Classic is one click away in Settings (New look).","Menus open as windows over the hunt. Use the dock or a key: H hunt, I inventory, P pack, L library, M mine, E events, N mail, O settings. Esc closes.","A target frame shows the creature you're fighting, its health, and what's on it: Burrs (bleeding), Scorched, Frostbit, Dazed, Thick Coat and more.","Your own buffs and debuffs show above the skill bar, and your equipped weapons sit bottom-right. Tap one to see its card.","New UI icons from game-icons.net (CC BY 3.0)."]},
  {v:"0.30", d:"2026-10-02", notes:["Windows can be dragged by their title bar, resized from the corner, and you can have several open at once. Closing one puts it back in its usual spot next time.","Mail is now a proper window. Each letter folds open when you click its title, with Accept, Take me there and Delete inside.","Hover any buff or debuff to see what it does, how many stacks and how long is left. Their timers now tick down smoothly. Health bars glide instead of jumping, and the target frame shows a light trail for the damage you just did. Mega bosses and gods now show in the target frame with their timer instead of the old bar.","New Interface size setting (70% to 130%) for smaller or bigger screens. You can also press − and = while playing."]},
  {v:"0.31", d:"2026-10-02", notes:["The Field Kit look is now the game's look. The old style is retired.","Messages and event alerts now stack neatly in the top-right corner under the area info, and new-mail notices join them in the new style.","Head home now lives on the dock, just above Settings (key D). At home it turns into Walk out to the Meadow.","Your buffs and debuffs now sit in the bar at the bottom, right above your skills, so they no longer look like something lying on the ground.","Skill shouts like Awoooo now pop up above your dingo."]},
  {v:"0.32", d:"2026-10-02", notes:["Big tidy-up under the hood: old systems that the game no longer uses (weapon rolling, the merge forge, the classic layout, the firefly and meat meteor events) were removed, so the game is lighter and easier to grow.","All messages now flow through one place. Repeated messages stack as ×2, ×3, and event banners wait their turn instead of piling on top of each other.","Every buff and debuff now comes from one shared list, so they look and read the same everywhere.","The Armory is rebuilt: your 5 equipped weapons up top, your weapons as slots below, and the selected weapon's card on the right.","Credits and the developer button now live at the bottom of Settings."]},
  {v:"0.33", d:"2026-10-02", notes:["Fixed: buttons, items and drop-downs inside windows ignored clicks. Picking a weapon, switching between Hunt and Armory, sorting, equip, lock and the tabs in the Inventory, Pack, Library and Mine windows all work again."]},
  {v:"0.34", d:"2026-10-02", notes:["The Trial wave tracker now matches the new look and always sits just under the creature frame, so a big Warden frame no longer covers it."]},
  {v:"0.35", d:"2026-10-02", notes:["Daily gifts now arrive in your Mail: one letter a day with today's gift, plus any earlier days this month you hadn't opened. The calendar under Trials is gone.","The Bandana picker is hidden for now. Your dingo still wears theirs."]},
  {v:"0.36", d:"2026-10-02", notes:["New Inventory (I), built like an MMO bag: a Loadout for your 5 weapons, three 20-slot Den Satchels and a Keepsake Box. Drag things anywhere, double-click to equip or use, right-click for more.","New things glow until you hover them, and the Inventory button counts them.","Tidy sorts your satchels. Salvage junk clears every Common and Uncommon weapon in one go (it asks first). Locked items, set pieces and the Keepsake Box are never touched.","When your bags are full, new finds wait in an overflow bag instead of being lost. It shows as a red badge on the Inventory button. Settings can make it pop open right away.","Your Stash: 200 spaces, opened from the new Den bar on the right when you're home. Send things there from anywhere (right-click, Send to Stash) and take them out at home.","The Library moved to the Den bar. The Armory and Scrapyard are now part of the Inventory.","Fresh start: saves were reset once for this update, before release."]},
  {v:"0.37", d:"2026-10-02", notes:["Bigger item icons in your bags and Stash.","Hovering a weapon now shows a bigger picture of it, and puts the equipped weapon it would replace right beside it (the same kind if you wear one, otherwise your weakest), with the differences marked.","Tidy and Salvage junk are now per bag, on each bag's header. Tidying one bag never touches the others.","Bags can be renamed, dragged to reorder in the bag strip, and stowed in the Stash with everything still inside (right-click a bag). Put a stowed bag back on from the Stash at home."]},
  {v:"0.38", d:"2026-10-02", notes:["Bag settings (the cog on each bag): choose what a bag pulls in (weapons, consumables, bait, anything, or nothing so you only fill it by hand) and which weapon rarities it takes, so you can have a Rare+ bag, a Common bag, a snack bag. New finds go to the first bag that asks for them.","Each bag can also pick its own sort, be protected from salvage, lock its layout so nothing rearranges it, and wear a colour tag. Gather matching items pulls everything a bag asks for in from your other bags.","Inventory cog: a default sort and a Tidy all button (locked bags are skipped), an auto-salvage level with a plain-words preview of exactly what it will take, ask-before-salvaging Rare or better, compare cards always, only while holding Shift, or off, New markers on or off with Mark all as seen, and show or hide empty slots and bag headers.","New tab: Recently salvaged. Your last 20 salvaged weapons, each with an Undo."]},
  {v:"0.39", d:"2026-10-02", notes:["Fixed: clicking a bag setting (like Common) could slide a window's insides up so its title bar and close button disappeared. A window's frame now never scrolls; only its contents do."]},
  {v:"0.40", d:"2026-10-02", notes:["The Den Stage: the game now fits itself to your screen. A laptop, a big monitor and a TV all show the same Meadow, just bigger or smaller, and fights take the same time on every screen. Resizing the window no longer changes the game.","The camera follows your dingo: it holds its spot and the Meadow scrolls past while it walks, then stops for fights. No more running off the edge and popping back on the other side.","Interface size is now Small, Normal, Large or Larger, on top of the automatic fit (Settings, or − and = in the game). Open windows stay on screen when you change it.","For now it's just the Meadow: the other areas and Trials are resting while the game changes a lot. Nothing you earned is lost.","Credits now have their own section in Settings, with a link for everything we use."]},
  {v:"0.41", d:"2026-10-02", notes:["Faster loading: the game page is about 7 times smaller. The art now comes in separate files your browser can keep between visits, and the extra art styles load after the game starts.","A new loading screen in the new look, so the old one no longer flashes up first.","The menu bar always stays on the left, even in a narrow window.","Camera zoom: use the scroll wheel over the Meadow (or Settings) to zoom in on your dingo, up to 2×. Scrolling inside windows still scrolls them.","Inventory: right-click a weapon to swap it straight in for the equipped one it's compared against."]},
  {v:"0.42", d:"2026-10-02", notes:["Fixed: some icons and creatures could show up blank after the faster-loading update. The art now loads a sturdier way, and your browser keeps a copy, so after the first visit it doesn't need downloading again. If it ever can't load, the game tells you instead of showing blanks."]},
  {v:"0.43", d:"2026-10-02", notes:["New weather: rain falls in streaks and splashes on the ground, snow drifts down and slowly piles up, fog rolls past in soft banks, and wind sends gusts across the sky.","Storms have real forked lightning that lights up the whole Meadow, with thunder built live: a crack, a deep boom, then a long rolling rumble. Rain and wind have soft background sounds too.","New lighting: dusk and night darken the Meadow while your dingo carries a warm glow, rare loot and fancy weapons shine, fireflies come out in the evening, and the sun throws rays across the sky by day.","Everything casts a soft shadow on the ground that leans away from the sun, or away from your dingo's glow at night.","Settings: Weather & lighting (Full, Light or Off), Gentle weather (on by default: softer rain, quieter thunder), and Weather sounds. If your computer struggles, the game switches to Light by itself and tells you.","Weather effects and thunder adapted from web-weather (MIT); credits in Settings."]},
  {v:"0.44", d:"2026-10-02", notes:["Hit sparks, crit bursts, kill puffs, weapon trails, lightning and rare loot pickups now share one particle system (Proton, MIT). They look richer and every effect follows the same rules.","Creatures no longer announce what they did in a pop-up. A debuff shows as its icon, and armor regrowing or a titan opening up shows as a short label in the Meadow.","The first mega boss win no longer opens a box: the banner and the loot on the ground say it all, same as every other win.","Welcome back: the time you were away shows as a banner and the haul goes to the loot feed and your bags, instead of a box you have to close.","Seasonal bait names only show while seasonal events are running.","The Pack no longer lists baskets from areas that are closed for now.","The den wall hooks stay hidden until you hang a weapon (Inventory → Hang on den wall).","Skill names on the bar stay on one line.","Two letters no longer point at retired things (rolling for weapons, and Meta trials while Trials are closed)."]},
  {v:"0.45", d:"2026-10-03", notes:["A new status engine runs every boon and condition on creatures: Burrs, Scorched, Frostbit and Stunned now stack, tick and expire through one system, and the target frame reads straight from it. Same numbers as before; the plumbing is new.","Creature traits (Armored, Shielded, Flying, Quick, Healer, Phasing) show as statuses too.","Meadow Trials are open again (the Events window and its letters). Other areas' trials stay closed with their areas."]},
  {v:"0.46", d:"2026-10-03", notes:["Your own buffs run on the status engine now: brews, treats, Sharp Nose, Rally Howl, Feast Frenzy and the mega bosses' debuffs are all statuses on your dingo, shown in one bar with their time left, and they survive a reload.","Brews that were running before the update carry over.","Same numbers as before."]},
  {v:"0.47", d:"2026-10-03", notes:["Every bonus in the game now answers to one engine: gems, scrolls, tomes, companions, upgrades, season, time of day, day of week, weather and your buffs all fold into one number per stat (damage, speed, luck, drops, coins, crit).","Creature Armored and Quick, Ironhide and Swift elites, and Shocked all run through it too, so a status that lowers armor really does make the hit land harder.","Meat Magnet brews now plainly boost drops (they always did; the label was muddled).","Same numbers as before, kill for kill."]},
  {v:"0.48", d:"2026-10-03", notes:["Skills run on the engine: Pounce, Zoomies Whirl, Rally Howl, Shadow Pack and Feast Frenzy are data now (level, cooldown, what they do), and auto-cast picks the first ready skill in bar order.","Pounce and Whirl no longer burn their cooldown when nothing is in reach.","Same numbers as before."]},
  {v:"0.49", d:"2026-10-03", notes:["Tells: every status now marks the drawing it sits on. Creatures carry their conditions as classes (Frostbit's chill is the first to use it); your dingo carries the reaction each status names (hackles, ears back, head low, howl). The new hero's rig will read these when he arrives.","Same numbers as before."]},
  {v:"0.50", d:"2026-10-03", notes:["The new hero is in the Meadow: a real Carolina Dog, two-tone, green collar, walking on a jointed rig drawn by PixiJS on one canvas under the field (the first slice of the Pixi port).","His ears go back when he's spooked or weakened, and lay back for a howl; the status engine drives it.","Pounce, Whirl and going home still ride the old animations for now; hats, scarves and costumes return as rig parts in a later slice.","Same numbers as before."]},
  {v:"0.51", d:"2026-10-03", notes:["The Meadow's creatures are the new ones: Burrs, Kindling, Clockhead, Puffball, Bramble, Mound, Fencepost, Hollowhorn and the Shade, each drawn on its own jointed rig by the field renderer. Every regular creature is drawn as the one that matches what it does (swarms are Burrs, quick things are Kindling, healers are Hollowhorns, and so on).","When a creature closes in to strike, it shows its tell: ember eyes, wire up, thorns out, seeds scattering, the puffball swelling, the Shade going solid.","Bosses and the big ones keep their old look for now. Names, numbers and drops are unchanged; this is the drawing, not the roster.","Same numbers as before."]},
  {v:"0.52", d:"2026-10-03", notes:["Fixed: in a Trial, Zoomies bred a new status chip every frame until the bar overflowed (the Trial's pace chip shared Zoomies' name). The pace chip is Trial Pace now, and the bar only ever shows one chip per status."]},
  {v:"0.53", d:"2026-10-03", notes:["Conditions have two shapes now, and every tooltip ends by telling you which: some stack up (Burrs, Scorched, Shocked: every hit is its own stack with its own timer and its own strength; the oldest falls off first), some stack longer, not stronger (Frostbit, Weakened, Sluggish, Dazzled, Spooked: a second hit adds time, up to a cap).","Scorched stacks up to 5 now instead of restarting. Shocked is new in play: lightning (storms, the Storms tome, the Tempest compendium) stacks it, 3% more damage taken per stack up to 10.","Buffs got their rule too, under the hood: Lesser, the thing itself, Greater. One of each size counts per stat. Nothing is tiered yet; the numbers come with the balance pass.","Potions will be able to cleanse conditions (the engine can; the potions don't yet)."]},
  {v:"0.54", d:"2026-10-03", notes:["The pale underside of the hero's tail sits flush with the tan now (it used to poke past the edge)."]},
];
function devlogUnseen(){ let s = ""; try { s = localStorage.getItem("dengame-logver") || ""; } catch(e){} const i = DEVLOG.findIndex(b => b.v === s); return i < 0 ? DEVLOG.length : DEVLOG.length - 1 - i; }
function openDevlog(){ try { localStorage.setItem("dengame-logver", DEVLOG[DEVLOG.length-1].v); } catch(e){} tickClock(); const ov = document.createElement("div"); ov.className = "sos-ov setov";
  ov.innerHTML = `<div class="sos-card setcard"><div class="jar-top"><h3>📜 What's new</h3><button class="x" data-close aria-label="Close">×</button></div><div class="devlog">${DEVLOG.slice().reverse().map((b,i) => `<details class="dlv"${i === 0 ? " open" : ""}><summary><b>Version ${esc(b.v)}</b> <span class="small">${esc(new Date(b.d + "T12:00").toLocaleDateString("en-US", {month:"short", day:"numeric", year:"numeric"}))}</span></summary><ul>${b.notes.map(t => `<li>${esc(t)}</li>`).join("")}</ul></details>`).join("")}</div></div>`;
  document.body.appendChild(ov); ov.addEventListener("click", e => { if (e.target === ov || e.target.closest("[data-close]")) ov.remove(); }); }

/* Gentle "new mail" notice */
function _showMail(m){ if (document.querySelector(".welcomeov")) return; const old = document.querySelector(".mailnote"); if (old) old.remove();
  const n = document.createElement("div"); n.className = "mailnote"; n.setAttribute("role", "status");
  n.innerHTML = `<span class="mnicon">${fkOn ? fkIcon("mailbox") : "📬"}</span><span class="mntext"><b>New mail</b><span class="small">${esc(m.subject || "A letter from the Den team")}</span></span><button class="go" data-mn="open">Open</button><button data-mn="later">Later</button>`;
  document.body.appendChild(n); sfx("chime");
  const close = () => { n.classList.add("out"); setTimeout(() => n.remove(), 350); };
  n.addEventListener("click", e => { const b = e.target.closest("[data-mn]"); if (!b) return; close(); if (b.dataset.mn === "open") openMail(); });
  setTimeout(() => { if (document.body.contains(n)) close(); }, 9000); }

/* Letters from the Den team */
const TEAM = "The Den Team";
function sendLetter(L){ const M = mailState(); if (M.some(x => x.id === L.id)) return null; tlog("letter", L.id); const m = Object.assign({read:false, claimed:false, ts: Date.now(), from: TEAM, date: new Date().toLocaleDateString("en-US", {month:"short", day:"numeric"})}, L); delete m.when; M.push(m); tickClock(); return m; }
const LETTERS = [
  {id:"l-welcome", when:() => true, welcome:true, subject:"🐾 Welcome to the Den!", items:[{bones:5},{treat:"pupcake", n:1}],
   body:"Hi there, and welcome! We're so happy you're here.\n\nPlease read this whole letter. It really helps.\n\nThis is an idle hunting game about a little canine and their growing pack. Your canine hunts on their own, even while you're busy, and gets stronger as you go.\n\nThe game opens up a piece at a time. Every time something new unlocks, we'll send you a letter like this one explaining how it works, sometimes with a little gift tucked inside. It's important to keep making progress so you don't get lost, and the letters are your map.\n\nThis is the only letter that asks you to confirm before closing. From now on, new mail will just arrive quietly with a small popup, and everything is always saved in the 📬 Mail button at the top.\n\nWe left a few bones and a treat below to get you started. Accept them, then head out and hunt!\n\nWith lots of love,\nThe Den Team 💛"},
  {id:"l-armory", when:() => hasLetter("l-welcome") && (huntState().kills||0) >= 5, subject:"🎒 Your Inventory", go:{tab:"bag"},
   body:"Look at you go! Every creature you beat drops meat 🍖, and now and then a weapon too.\n\nWeapons come from the wild. Each area has its own look, and creatures like to drop the weapon that beats their kind: flyers drop slingshots and bows, tough-hided ones drop things that bonk.\n\nYour canine carries up to five at once in the Loadout, and they fly out to hit whatever's nearby. Open your Inventory (I) to see what you've found: drag a weapon into the Loadout, or double-click it, to equip it. We'll be cheering. 🐾"},
  {id:"l-forge", when:() => (huntState().rolls||0) + (huntState().drops||0) >= 3, subject:"🎒 Keeping your bags tidy", items:[{bones:3}], go:{tab:"bag"},
   body:"Your bags are starting to fill up! Here's how to keep them tidy.\n\n♻️ Right-click a weapon you don't need and pick Salvage, or press Salvage junk to clear out every Common and Uncommon at once. Lock your favorites (right-click → Lock) or tuck them in the Keepsake Box so they're never salvaged.\n\n🔐 Your Stash in the Den holds 200 more things. You can send things there from anywhere (right-click → Send to Stash).\n\n✨ Better weapons have more affixes: Uncommon has one, Rare two, Epic three, and Legendary three plus a special power. The fiery-looking ones really do burn things.\n\nA few bones are tucked in here for you. 🐾"},
  {id:"l-pack", when:() => playerLevel() >= 2, subject:"🐕 Your Pack", items:[{starterPup:true}], go:{tab:"pack"},
   body:"Level 2! Your canine doesn't have to hunt alone anymore.\n\nPups join your pack and help hunt. You rescue them in the Pack tab, each one giving a pup in need a loving home, and each one adds a little damage and a little bonus. Rarer pups help more, and three of the same pup can be fused into a stronger one.\n\nWe've sent you a sweet little pup to start your pack. Accept it, and they'll come running. 🐶"},
  {id:"l-events", when:() => !SHELVED.trials && playerLevel() >= 2 && trialReady("meadow"), subject:"🏆 Trials and daily gifts", go:{tab:"events"},
   body:"Something fun is waiting in the Events tab.\n\n🏆 Trials are a run of ten waves in one area. Clear each wave before its timer runs out. Every wave you clear earns Trial Points.\n\n🎟️ Trial Points fill your Trial Pass, which has rewards all the way up.\n\n🗓️ There's also a daily gift for every day of the month. Missed a day? You can still open it later.\n\nGood luck out there! 🐾"},
  {id:"l-upgrades", when:() => !DISABLED.upgrades && playerLevel() >= 3, subject:"⬆️ Upgrades and your den", items:[{bones:3}], go:{tab:"upgrades"},
   body:"Level 3, hooray! A new tab just opened: Upgrades.\n\nUpgrades are permanent. They make every hunt a little better, forever: sharper fangs, quicker paws, a better nose. A few bones are tucked in here to help with your first upgrade. 💛"},
  {id:"l-lvl4", when:() => playerLevel() >= 4, subject:"🪤 Bait and 🧩 Sniffle", go:{tab:"hunt", view:"bait"},
   body:"Level 4! Something new to try.\n\n🪤 Bait (in the Hunt menu): craft lures that bring more creatures out to play for a while. More creatures, more meat.\n\nHave fun! 🐾"},
  {id:"l-gift-250", when:() => (huntState().kills||0) >= 250, subject:"🎁 250 hunts!", items:[{bones:5},{treat:"apple", n:1}],
   body:"Two hundred and fifty creatures! Your canine is turning into a real hunter.\n\nWe wanted to say we're proud of you, so here's a little something for the road.\n\nKeep being awesome. 💛"},
  {id:"l-gift-trial", when:() => Object.keys(trialState().clears).length > 0, subject:"🏆 Your first Trial clear!", items:[{bones:8},{coins:3}],
   body:"You cleared a whole Trial! Ten waves, every one beaten before the timer ran out. That's no small thing.\n\nHere are some bones and coins to celebrate. Go treat yourself (and your canine). 🐾"},
  {id:"l-gift-7", when:() => playerLevel() >= 7, subject:"🌟 Level 7, look at you!", items:[{bones:6},{treat:"broth", n:2}],
   body:"Level 7! Your pack has grown, your gear is shining, and the woods know your name.\n\nA couple of warm bone broths are tucked in here. Take a cozy break whenever you need one. 🍵"},
  {id:"l-library", when:() => { const T = state.tomes; return !!(T && T.inv && Object.values(T.inv).some(n => n > 0)); }, subject:"📚 You found a book!", go:{tab:"tomes"},
   body:"A creature dropped a Tome! Those are special.\n\nIn the Library you can equip tomes for lasting bonuses, like more damage or more meat. Collect copies of the same tome to make it stronger.\n\nTake a peek when you have a moment. 📖"},
  {id:"l-gather", when:() => playerLevel() >= 5 && hasLetter("l-library"), subject:"🫙 Essences and the Tome of Gathering", items:[{tome:"gather0"}], go:{tab:"tomes", view:"tomes"},
   body:"Level 5! Time to learn about essences.\n\nEvery creature carries a little essence: Ember, Tide, Wild, Night, Spark and Bone. But essences only drop while you have a Tome of Gathering equipped in the Library.\n\nWe've tucked your first Tome of Gathering into this letter. Accept it, then equip it in Library → Tomes. Like every tome, finding more copies makes it stronger, so you'll gather more essence over time.\n\n⚗️ The Alembic is open now too. It distills two essences into a rarer one.\n\nHappy gathering! 💛"},
  {id:"l-brew", when:() => hasLetter("l-gather") && Object.entries(POT_BREW.str).every(([a,n]) => (scripState().ess[a]||0) >= n), subject:"🧪 You can brew now!", go:{tab:"tomes", view:"apo"},
   body:"You've gathered enough essence for your very first Strength Brew!\n\nThe Apothecary in the Library turns essences into brews. Drink one and your canine gets a boost for a while: more damage, more speed, more luck, more meat. Stronger brews need rarer essences from the Alembic.\n\nGo brew something wonderful. 🧪"},
  {id:"l-scrolls", when:() => playerLevel() >= 10 && hasLetter("l-library"), subject:"📜 Scrolls, Research and Compendiums", items:[{bones:10}], go:{tab:"tomes", view:"research"},
   body:"Level 10! You've come such a long way. 💛\n\nThe deepest part of the Library is open to you now. Research unlocks Scrolls, which are permanent upgrades, and Compendiums bundle powerful bonuses you can shelve.\n\nHere are some bones to celebrate. We're proud of you!"},
  {id:"l-big", when:() => { const K = state.pack; return hasLetter("l-gather") && !!(K && (K.pups||[]).some(p => p.r === "huge")); }, subject:"⛏️ A Big pup, and the Crystal Caves", go:{tab:"mine"},
   body:"WOW, a Big pup! Those are rare.\n\nBig pups can be powered up with gems, and gems come from the Crystal Caves in the Mine tab. Dig for rough gems, cut them in the gem workshop, and inscribe them into your Big pups using the essences you've been gathering.\n\nGo show off that pup! ✨"}
];
function struggling(){ const H = huntState(); return shopState().coins < 1 && H.meats < MEAT_PER_COIN; }
function helpLetters(){ const out = [], SL = lettersSent(), sent = Object.keys(SL).filter(id => /^l-help-\d$/.test(id)); if (sent.length >= 5 || !hasLetter("l-armory")) return out;
  const n = sent.length + 1, last = Math.max(0, ...Object.entries(SL).filter(([id]) => id === "l-armory" || /^l-help-/.test(id)).map(([,t]) => t || 0));
  const lines = ["Hey there, we've noticed things have been a little slow, and that's okay. Every canine starts small.",
    "Hey bud, just checking in. Coins can be tricky to come by early on, so we wanted to help a little.",
    "Hi again! We see you're still working on those coins. You're doing great, honestly. Here's a little boost.",
    "Hey friend, we haven't forgotten you. Here's another little care package from all of us.",
    "One more little hug from the Den Team. After this, you've got this on your own, and we'll be cheering the whole way."];
  out.push({id:"l-help-" + n, when:() => struggling() && Date.now() - last > 10*60000, subject:"💛 A little help from the Den", items:[{coins:5}, {blessing:["str","cur"], mins:30}], go:{tab:"hunt", view:"armory"},
    body: lines[n-1] + "\n\nWe've sent some blessings your way: a Strength Brew and a Meat Magnet will start working the moment you accept, for 30 minutes. That means more damage and more meat while they last.\n\nThere are also 5 coins in here, a little something for later. Keep hunting: every creature might drop something wonderful.\n\nWe're rooting for you. 🐾\nThe Den Team"}); return out; }
function zoneLetters(){ const out = []; Object.entries(ZONES).forEach(([z, Z]) => { const nm = Z.name;
  if (SHELVED.zones.includes(z)) return;
  if (!Z.home) out.push({id:"l-trial-" + z, when:() => !SHELVED.trials && hasLetter("l-events") && playerLevel() >= trialLvl(z) && trialReady(z), subject:"🏆 " + nm + " Trial is ready", go:{tab:"events"},
    body:"You've gotten really comfortable hunting in " + nm + ", so its Trial is open now!\n\nSame rules as before: ten waves, each with a timer, with Trial Wardens on waves 5 and 10. Harder areas give more Trial Points per wave.\n\nWe believe in you! 🐾"});
  out.push({id:"l-op-" + z, when:() => (hasLetter("l-events") || SHELVED.trials) && zoneOP(z), subject:"✨ Overpowered in " + nm + "!", go:{tab:"tomes", view:"best"},
    body:"Whoa. The creatures of " + nm + " barely slow you down anymore. You're officially overpowered there!\n\n" + (SHELVED.trials ? "Something just opened up:" : "Two things just opened up:") + "\n\n📖 " + nm + "'s pages in the Bestiary (Library → Bestiary). Every creature you've beaten there is written up, with their traits and your star progress." + (SHELVED.trials ? "" : "\n\n♾️ Meta mode for the " + nm + " Trial (Events tab). There's no timer. Instead a power bar slowly drains, and your damage fills it back up. The waves keep getting tougher forever, until only the elders are left. See how far you can go!") + "\n\nSo proud of you. 💛"}); }); return out; }
function lettersSent(){ const SL = state.lettersSent = state.lettersSent || {}; mailState().forEach(m => { if (m && m.id && !(SL[m.id] > 1)) SL[m.id] = m.ts || 1; }); return SL; }
function checkLetters(){ if (!state || !isHost()) return; let sent = null; const SL = lettersSent();
  for (const L of LETTERS.concat(zoneLetters(), helpLetters())){ if (SL[L.id] || mailState().some(x => x.id === L.id)) continue; let ok = false; try { ok = L.when(); } catch(e){} if (!ok) continue; sent = sendLetter(L); if (sent && sent.welcome){ save("Welcome!", true); openWelcome(sent); return; } break; }
  if (!sent) sent = dailyGiftLetter();
  if (sent){ save("New mail", true); mailNotice(sent); } }
/* Daily gifts arrive by mail: one letter a day, carrying today's gift plus any earlier days this month that were never opened */
function dailyGiftLetter(){ if (!mailState().length) return null; const day = todayIso(), id = "daily-" + day; if (hasLetter(id)) return null;
  const S = trialState(), ym = day.slice(0,7), today = new Date().getDate(), dim = giftDim(ym), pend = mailState().filter(m => !m.claimed).flatMap(m => (m.items||[]).filter(it => it.daily).map(it => it.ym + "-" + it.daily));
  const days = []; for (let d = 1; d <= today; d++) if (!S.gifts[ym + "-" + d] && !pend.includes(ym + "-" + d)) days.push(d); if (!days.length) return null;
  const g = giftFor(today, dim), missed = days.length - (days.includes(today) ? 1 : 0);
  return sendLetter({id, subject: "Daily gift · Day " + today + (g.big ? " 🎁" : ""), body: "Here's today's gift from the Den Team. 🐾" + (missed ? "\n\nWe also tucked in " + missed + " gift" + (missed === 1 ? "" : "s") + " from earlier this month that you hadn't opened yet." : ""), items: days.map(d => ({daily: d, ym}))}); }
setInterval(checkLetters, 4000);
function openWelcome(m){ if (document.querySelector(".welcomeov")) return; m.read = true; const ov = document.createElement("div"); ov.className = "sos-ov welcomeov";
  ov.innerHTML = `<div class="sos-card welcomecard"><p class="readall">📖 Please read the whole letter. It really helps.</p><h2>${esc(m.subject)}</h2><p class="lbody">${esc(m.body).replace(/\n/g,"<br>")}</p>
    <div class="mitems">${(m.items||[]).map(it => { const [i,l] = itemLabel(it); return `<span class="mitem" style="background:var(--panel-2);border-color:var(--line)">${emoImg(i)}<b>${esc(l)}</b></span>`; }).join("")}</div>
    <div class="btns wfoot" style="justify-content:center;margin-top:12px"><button class="go" data-wc="accept">🎁 Accept gifts and start</button><button data-wc="close">Close</button></div><div class="wwarn" hidden><p><b>Are you sure?</b> You can read this letter again anytime from the 📬 Mail button at the top.</p><div class="btns" style="justify-content:center"><button class="go" data-wc="sure">Yes, close it</button><button data-wc="back">Keep reading</button></div></div></div>`;
  document.body.appendChild(ov);
  ov.addEventListener("click", e => { const b = e.target.closest("[data-wc]"); if (!b) return; const k = b.dataset.wc;
    if (k === "accept"){ claimMail(m.id); save("Welcome gifts"); ov.remove(); }
    if (k === "close"){ ov.querySelector(".wwarn").hidden = false; ov.querySelector(".wwarn").scrollIntoView({block:"nearest"}); }
    if (k === "back") ov.querySelector(".wwarn").hidden = true;
    if (k === "sure"){ ov.remove(); save("Welcome read", true); } }); }
function goMail(go){ document.querySelectorAll(".mailov").forEach(o => o.remove()); if (!go) return; if (go.tab === "hunt" && (go.view === "armory" || go.view === "scrap")) go = {tab:"bag"}; if (fkOn){ if (go.view){ if (go.tab === "hunt") huntState().view = go.view; if (go.tab === "pack") packState().view = go.view; if (go.tab === "mine") gemState().view = go.view; if (go.tab === "tomes") libState().view = go.view; if (go.tab === "bag") state.bagView = go.view; } fkOpen(go.tab || "hunt", true); render(); return; } tab = go.tab || tab; try { localStorage.setItem("dengame-tab", tab); } catch(e){}
  if (go.view){ if (go.tab === "hunt") huntState().view = go.view; if (go.tab === "pack") packState().view = go.view; if (go.tab === "mine") gemState().view = go.view; if (go.tab === "tomes") libState().view = go.view; if (go.tab === "bag") state.bagView = go.view; }
  render(); setTimeout(() => { const t = document.getElementById("subnav") || document.querySelector("section.hero"); if (t) t.scrollIntoView({behavior:"smooth", block:"start"}); }, 120); }

/* Unlocks: one place that decides what's open (all open for now; gating comes in the next phase) */
function hasLetter(id){ return !!(state && ((state.lettersSent && state.lettersSent[id]) || (state.mail && state.mail.some(m => m.id === id)))); }
const UNLOCKS = {
  hunt:() => true, "hunt-hunt":() => true, "hunt-armory":() => true,
  bag:() => true, stash:() => true,
  "hunt-forge":() => false /* merge forge retired in v0.21 */, "hunt-scrap":() => hasLetter("l-forge"),
  pack:() => hasLetter("l-pack"),
  events:() => hasLetter("l-events"),
  upgrades:() => hasLetter("l-upgrades"),
  "hunt-bait":() => hasLetter("l-lvl4"), selfcare:() => !!(state && state.selfCareOn),
  tomes:() => hasLetter("l-library"), "lib-tomes":() => true, "lib-best":() => hasLetter("l-library"),
  "lib-alembic":() => hasLetter("l-gather"), "lib-apo":() => hasLetter("l-brew"), "lib-research":() => hasLetter("l-scrolls"),
  mine:() => hasLetter("l-big")
};
/* Disabled for now (v0.27): systems that don't fit the current game. Code is kept. */
const DISABLED = {upgrades:true, "hunt-forge":true, seasonal:true /* v0.45: Trials are back for the Meadow; seasonal bait names stay off */};
function isUnlocked(k){ if (DISABLED[k]) return false; if (k === "selfcare") return !!(state && state.selfCareOn); /* WIP: only when switched on in Settings, even in dev mode */ if (devOn) return true; const f = UNLOCKS[k]; if (!f) return true; if (!state) return false; state.unlocks = state.unlocks || {}; if (state.unlocks[k]) return true; let ok = false; try { ok = !!f(); } catch(e){} if (ok){ state.unlocks[k] = true; tlog("unlock", k); } return ok; }

/* Bandana: always worn; colors are earned */
const BANDANAS = {red:["Den Red","#d0453b"], sky:["Sky Blue","#4f8fb8"], forest:["Forest Green","#3f8a4f"], sun:["Sunny Gold","#e3b23c"], plum:["Plum","#8a5ac0"], rose:["Rose","#e07aa0"], night:["Midnight","#2a3248"], snow:["Snow","#eef2f6"]};
function bandanaState(){ state.bandana = state.bandana || {color:"red", owned:{red:true}}; state.bandana.owned = state.bandana.owned || {red:true}; state.bandana.owned.red = true; return state.bandana; }
function giveBandana(k){ const S = bandanaState(); if (!BANDANAS[k] || S.owned[k]) return false; S.owned[k] = true; toast("🎀 New bandana color: " + BANDANAS[k][0] + "!"); return true; }
function applyBandana(){ const d = $("#dingo"); if (!d || !state) return; const S = bandanaState(); d.style.setProperty("--bandana", (BANDANAS[S.color] || BANDANAS.red)[1]); }
function bandanaSection(){ const S = bandanaState();
  return `<section class="box" aria-labelledby="band-h"><div class="jar-top"><h2 id="band-h">🎀 Bandana</h2><span class="small">${Object.keys(S.owned).length}/${Object.keys(BANDANAS).length} colors</span></div><p class="hint">Your canine always wears their bandana. More colors are coming later.</p><div class="bandrow">${Object.entries(BANDANAS).map(([k,[n,c]]) => S.owned[k] ? `<button class="bandsw${S.color === k ? " on" : ""}" data-a="bandana" data-id="${k}" title="${esc(n)}"><i style="background:${c}"></i><span class="small">${esc(n)}</span></button>` : `<span class="bandsw locked" title="Not earned yet"><i></i><span class="small">???</span></span>`).join("")}</div></section>`; }

